#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/heaviside.h"

/**
* Evaluates the Heaviside function.
*
* @param x 				input value
* @param continuity 	continuity option
* @return				function value
*
* @example
* double v = stdlib_base_heaviside( 3.14, 0 );
* // returns 1.0
*
* @example
* double v = stdlib_base_heaviside( -3.14, 1 );
* // returns 0.0
*
* @example
* double v = stdlib_base_heaviside( 0.0, -1 );
* // returns NaN
*
* @example
* double v = stdlib_base_heaviside( 0.0, 2 );
* // returns 0.5
*
* @example
* double v = stdlib_base_heaviside( 0.0, 0 );
* // returns 0.0
*
* @example
* double v = stdlib_base_heaviside( 0.0, 1 );
* // returns 1.0
*
* @example
* double v = stdlib_base_heaviside( NaN, 0 );
* // returns NaN
*/
double stdlib_base_heaviside( const double x, int continuity ) {
	if ( stdlib_base_is_nan( x )) {
		return 0.0/0.0;
	}
	if ( x > 0.0 ) {
		return 1.0;
	}
	if ( x == 0.0 ) {
		if ( continuity == 0 ) {
			return 0.0;
		}else if ( continuity == 1 ) {
			return 1.0;
		}else if ( continuity == 2 ) {
			return 0.5;
		}
		// Default behaviour is discontinuity
		return 0.0/0.0;
	}
	return 0.0;
}
